bird_classifier = None # empty until the first time someone asks for it

def get_bird_classifier():
    """Load the bird species model the first time we need it (it's a big download)."""
    global bird_classifier

    if bird_classifier is None:
        from transformers import pipeline

        bird_classifier = pipeline(
            task="image-classification",
            model="dennisjooo/Birds-Classifier-EfficientNetB2",
        )

    return bird_classifier


# %% ../tutorials/05-identify.ipynb #9dc77706
@dataclass
class BirdClassifier(ImageClassifier):

    def classify(self, debug_prn: bool = False):

        classifier = get_bird_classifier()

        results = classifier(self.img, top_k=3)

        guesses = [SpeciesGuess(species=res['label'], confidence=res['score']) for res in results]

        if debug_prn:
            for guess in guesses:
                print(guess.summary())

        self.guesses = guesses
        return guesses[0]


