from PIL.ImageDraw import ImageDraw


class ImageClassifierEnum(Enum):
    BIRD = BirdClassifier
    DOG = DogClassifier


@patch_to(Detection)
def __post_init__(self):
    classifier_enum = ImageClassifierEnum.__members__.get(self.label.upper())
    if classifier_enum is None:
        self.Classifier = None
        return
    self.Classifier = classifier_enum.value(self.cropped_image)


@patch_to(AnnotatedImage,as_prop = True)
def image_w_classifications(self) -> PILImage.Image:
    annotated = self.image.copy()

    draw = ImageDraw.Draw(annotated)

    for detection in self.detections:
        x_min, y_min, x_max, y_max = detection.BoundingBox.to_tuple()
        draw.rectangle([x_min, y_min, x_max, y_max], outline="red", width=2)
        draw.text((x_min, y_min), detection.Classifier.class_name if detection.Classifier is not None else detection.label, fill="red")

        return annotated
